SELECT

FROM
    dm_approval


        AND
        owner_uid IN

            #{item}



         AND gmt_create > #{ticketQuery.startTime} 


         AND gmt_create < #{ticketQuery.endTime} 


         AND id = #{ticketQuery.ticketId} 


         AND biz_id = #{ticketQuery.ticketBizId} 


         AND ticket_title LIKE CONCAT('%', #{ticketQuery.ticketTitleName}, '%') 



            AND
            description LIKE CONCAT('%', #{ticketQuery.ticketDescription}, '%')




            AND
            content_type = 'INLINE'
            AND
            raw_sql      LIKE CONCAT('%', #{ticketQuery.ticketContent}, '%')



         AND ticket_status = #{ticketQuery.ticketStatus,javaType=com.clougence.clouddm.platform.dal.model.approval.ApprovalStatus} 


        AND
        bind_ds_id IN

            #{item}



        AND
        (
            appro_template_identity NOT LIKE 'CUSTOM-%'
            OR
            owner_uid = #{ticketQuery.viewerUid}
            OR
            primary_uid = #{ticketQuery.viewerUid}

                OR
                id IN

                    #{ticketId}


        )

    AND
    primary_uid = #{puid}
    AND
    deleted     = false

ORDER BY
    gmt_create DESC

SELECT
FROM dm_approval
AND owner_uid IN
#{item}
AND gmt_create > #{ticketQuery.startTime}
AND gmt_create < #{ticketQuery.endTime}
AND id = #{ticketQuery.ticketId}
AND biz_id = #{ticketQuery.ticketBizId}
AND ticket_title LIKE CONCAT('%', #{ticketQuery.ticketTitleName}, '%')
AND description LIKE CONCAT('%', #{ticketQuery.ticketDescription}, '%')
AND content_type = 'INLINE' AND raw_sql LIKE CONCAT('%', #{ticketQuery.ticketContent}, '%')
AND ticket_status = #{ticketQuery.ticketStatus,javaType=com.clougence.clouddm.platform.dal.model.approval.ApprovalStatus}
AND primary_uid = #{ticketQuery.primaryUid}
AND id IN
#{ticketId}
AND 1 = 0
AND deleted = false AND ticket_status IN ('WAIT_CONFIRM', 'WAIT_APPROVAL', 'WAIT_EXEC')
ORDER BY gmt_create DESC

SELECT

FROM
    dm_approval

    appro_identity = #{approIdentity}
    AND
    appro_type     = #{type}
    AND
    deleted        = false

        AND
        primary_uid = #{puid}

SELECT
FROM dm_approval
AND owner_uid IN
#{item}
AND gmt_create > #{ticketQuery.startTime}
AND gmt_create < #{ticketQuery.endTime}
AND ticket_title LIKE CONCAT('%', #{ticketQuery.ticketTitleName}, '%')
AND ticket_status = #{ticketQuery.ticketStatus,javaType=com.clougence.clouddm.platform.dal.model.approval.ApprovalStatus}
AND appro_biz = 'DATA_SOURCE_AUTH' AND deleted = false
ORDER BY gmt_create DESC
